namespace ComplianceTracker.Infrastructure.Persistence
{
    // US-069: version 2 of the built-in CRA. Annex I is carried over with the same codes, titles and texts (R6), so
    // links, "not applicable" and evidence can follow a project that moves (VersionCarryOver). The manufacturer's
    // obligations in Art. 13, 14 and 28–32 and Annexes II and VII are added (R3–R5).
    //
    // The description is the official English text from EUR-Lex (OJ L, 2024/2847, 20.11.2024), checked 05-11-2026.
    // Where a paragraph has a lead-in ("... shall submit:"), it is put in front of each point. Where a requirement is
    // made from several subparagraphs, they are joined with a space and the Commission's own powers are left out.
    // The title is a short summary in our own words. Which paragraphs are left out, and why: docs/daekning-af-regulativer.md.
    public static class BuiltInCraRequirementsV2
    {
        public const string Art13 = "Art. 13 – Obligations of manufacturers";
        public const string Art14 = "Art. 14 – Reporting obligations";
        public const string Conformity = "Art. 28–32 – Conformity assessment and CE marking";
        public const string AnnexII = "Annex II – Information and instructions to the user";
        public const string AnnexVII = "Annex VII – Technical documentation";

        private const string Source = "https://eur-lex.europa.eu/legal-content/EN/TXT/HTML/?uri=OJ:L_202402847";

        private const string Art14Point2 = "For the purposes of the notification referred to in paragraph 1, the manufacturer shall submit: ";
        private const string Art14Point4 = "For the purposes of the notification referred to in paragraph 3, the manufacturer shall submit: ";
        private const string AnnexIILeadIn = "At minimum, the product with digital elements shall be accompanied by: ";
        private const string AnnexVIILeadIn = "The technical documentation referred to in Article 31 shall contain at least the following information, as applicable to the relevant product with digital elements: ";

        public record Item(Guid Id, int Position, string Group, string Code, string Title, string Description, string Reference);

        public static readonly IReadOnlyList<Item> All = Build();

        private static List<Item> Build()
        {
            // R6: Annex I as in version 1, with new ids (a requirement belongs to one version)
            var items = BuiltInCraRequirements.All
                .Select(i => new Item(Id(i.Position), i.Position, i.Group, i.Code, i.Title, i.Description, BuiltInCraRequirements.Reference))
                .ToList();

            void Add(string group, string anchor, string code, string title, string description)
                => items.Add(new Item(Id(items.Count + 1), items.Count + 1, group, code, title, description, $"{Source}#{anchor}"));

            // ------------------------------------------------------------------ Art. 13
            Add(Art13, "art_13", "Art.13(2)", "Cybersecurity risk assessment, used in every phase",
                "For the purpose of complying with paragraph 1, manufacturers shall undertake an assessment of the cybersecurity risks associated with a product with digital elements and take the outcome of that assessment into account during the planning, design, development, production, delivery and maintenance phases of the product with digital elements with a view to minimising cybersecurity risks, preventing incidents and minimising their impact, including in relation to the health and safety of users.");
            Add(Art13, "art_13", "Art.13(3)", "The risk assessment is documented and kept up to date",
                "The cybersecurity risk assessment shall be documented and updated as appropriate during a support period to be determined in accordance with paragraph 8 of this Article. That cybersecurity risk assessment shall comprise at least an analysis of cybersecurity risks based on the intended purpose and reasonably foreseeable use, as well as the conditions of use, of the product with digital elements, such as the operational environment or the assets to be protected, taking into account the length of time the product is expected to be in use. The cybersecurity risk assessment shall indicate whether and, if so in what manner, the security requirements set out in Part I, point (2), of Annex I are applicable to the relevant product with digital elements and how those requirements are implemented as informed by the cybersecurity risk assessment. It shall also indicate how the manufacturer is to apply Part I, point (1), of Annex I and the vulnerability handling requirements set out in Part II of Annex I.");
            Add(Art13, "art_13", "Art.13(4)", "The risk assessment is in the technical documentation, with reasons for what does not apply",
                "When placing a product with digital elements on the market, the manufacturer shall include the cybersecurity risk assessment referred to in paragraph 3 of this Article in the technical documentation required pursuant to Article 31 and Annex VII. For products with digital elements as referred to in Article 12, which are also subject to other Union legal acts, the cybersecurity risk assessment may be part of the risk assessment required by those Union legal acts. Where certain essential cybersecurity requirements are not applicable to the product with digital elements, the manufacturer shall include a clear justification to that effect in that technical documentation.");
            Add(Art13, "art_13", "Art.13(5)", "Due diligence on components from third parties",
                "For the purpose of complying with paragraph 1, manufacturers shall exercise due diligence when integrating components sourced from third parties so that those components do not compromise the cybersecurity of the product with digital elements, including when integrating components of free and open-source software that have not been made available on the market in the course of a commercial activity.");
            Add(Art13, "art_13", "Art.13(6)", "Vulnerabilities in a component are reported to its maintainer",
                "Manufacturers shall, upon identifying a vulnerability in a component, including in an open source-component, which is integrated in the product with digital elements report the vulnerability to the person or entity manufacturing or maintaining the component, and address and remediate the vulnerability in accordance with the vulnerability handling requirements set out in Part II of Annex I. Where manufacturers have developed a software or hardware modification to address the vulnerability in that component, they shall share the relevant code or documentation with the person or entity manufacturing or maintaining the component, where appropriate in a machine-readable format.");
            Add(Art13, "art_13", "Art.13(7)", "Cybersecurity aspects and known vulnerabilities are documented",
                "The manufacturers shall systematically document, in a manner that is proportionate to the nature and the cybersecurity risks, relevant cybersecurity aspects concerning the products with digital elements, including vulnerabilities of which they become aware and any relevant information provided by third parties, and shall, where applicable, update the cybersecurity risk assessment of the products.");
            Add(Art13, "art_13", "Art.13(8)", "A support period of at least five years, and how it was determined",
                "Manufacturers shall ensure, when placing a product with digital elements on the market, and for the support period, that vulnerabilities of that product, including its components, are handled effectively and in accordance with the essential cybersecurity requirements set out in Part II of Annex I. "
                + "Manufacturers shall determine the support period so that it reflects the length of time during which the product is expected to be in use, taking into account, in particular, reasonable user expectations, the nature of the product, including its intended purpose, as well as relevant Union law determining the lifetime of products with digital elements. When determining the support period, manufacturers may also take into account the support periods of products with digital elements offering a similar functionality placed on the market by other manufacturers, the availability of the operating environment, the support periods of integrated components that provide core functions and are sourced from third parties as well as relevant guidance provided by the dedicated administrative cooperation group (ADCO) established pursuant to Article 52(15) and the Commission. The matters to be taken into account in order to determine the support period shall be considered in a manner that ensures proportionality. "
                + "Without prejudice to the second subparagraph, the support period shall be at least five years. Where the product with digital elements is expected to be in use for less than five years, the support period shall correspond to the expected use time. "
                + "Manufacturers shall include the information that was taken into account to determine the support period of a product with digital elements in the technical documentation as set out in Annex VII. "
                + "Manufacturers shall have appropriate policies and procedures, including coordinated vulnerability disclosure policies, referred to in Part II, point (5), of Annex I to process and remediate potential vulnerabilities in the product with digital elements reported from internal or external sources.");
            Add(Art13, "art_13", "Art.13(9)", "Security updates stay available for at least 10 years",
                "Manufacturers shall ensure that each security update, as referred to in Part II, point (8), of Annex I, which has been made available to users during the support period, remains available after it has been issued for a minimum of 10 years or for the remainder of the support period, whichever is longer.");
            Add(Art13, "art_13", "Art.13(12)", "Technical documentation, conformity assessment, declaration and CE marking before sale",
                "Before placing a product with digital elements on the market, manufacturers shall draw up the technical documentation referred to in Article 31. "
                + "They shall carry out the chosen conformity assessment procedures as referred to in Article 32 or have them carried out. "
                + "Where compliance of the product with digital elements with the essential cybersecurity requirements set out in Part I of Annex I and of the processes put in place by the manufacturer with the essential cybersecurity requirements set out in Part II of Annex I has been demonstrated by that conformity assessment procedure, manufacturers shall draw up the EU declaration of conformity in accordance with Article 28 and affix the CE marking in accordance with Article 30.");
            Add(Art13, "art_13", "Art.13(13)", "Documentation and declaration are kept for at least 10 years",
                "Manufacturers shall keep the technical documentation and the EU declaration of conformity at the disposal of the market surveillance authorities for at least 10 years after the product with digital elements has been placed on the market or for the support period, whichever is longer.");
            Add(Art13, "art_13", "Art.13(14)", "Products made in series stay in conformity",
                "Manufacturers shall ensure that procedures are in place for products with digital elements that are part of a series of production to remain in conformity with this Regulation. Manufacturers shall adequately take into account changes in the development and production process or in the design or characteristics of the product with digital elements and changes in the harmonised standards, European cybersecurity certification schemes or common specifications as referred to in Article 27 by reference to which the conformity of the product with digital elements is declared or by application of which its conformity is verified.");
            Add(Art13, "art_13", "Art.13(15)", "A type, batch or serial number identifies the product",
                "Manufacturers shall ensure that their products with digital elements bear a type, batch or serial number or other element allowing their identification, or, where that is not possible, that that information is provided on their packaging or in a document accompanying the product with digital elements.");
            Add(Art13, "art_13", "Art.13(16)", "The manufacturer's name and contact details",
                "Manufacturers shall indicate the name, registered trade name or registered trademark of the manufacturer, and the postal address, email address or other digital contact details, as well as, where applicable, the website where the manufacturer can be contacted, on the product with digital elements, on its packaging or in a document accompanying the product with digital elements. That information shall also be included in the information and instructions to the user set out in Annex II. The contact details shall be in a language which can be easily understood by users and market surveillance authorities.");
            Add(Art13, "art_13", "Art.13(17)", "A single point of contact for users",
                "For the purposes of this Regulation, manufacturers shall designate a single point of contact to enable users to communicate directly and rapidly with them, including in order to facilitate reporting on vulnerabilities of the product with digital elements. "
                + "Manufacturers shall ensure that the single point of contact is easily identifiable by the users. They shall also include the single point of contact in the information and instructions to the user set out in Annex II. "
                + "The single point of contact shall allow users to choose their preferred means of communication and shall not limit such means to automated tools.");
            Add(Art13, "art_13", "Art.13(18)", "Information and instructions to the user, kept for at least 10 years",
                "Manufacturers shall ensure that products with digital elements are accompanied by the information and instructions to the user set out in Annex II, in paper or electronic form. Such information and instructions shall be provided in a language which can be easily understood by users and market surveillance authorities. They shall be clear, understandable, intelligible and legible. They shall allow for the secure installation, operation and use of products with digital elements. Manufacturers shall keep the information and instructions to the user set out in Annex II at the disposal of users and market surveillance authorities for at least 10 years after the product with digital elements has been placed on the market or for the support period, whichever is longer. Where such information and instructions are provided online, manufacturers shall ensure that they are accessible, user-friendly and available online for at least 10 years after the product with digital elements has been placed on the market or for the support period, whichever is longer.");
            Add(Art13, "art_13", "Art.13(19)", "The end date of the support period is shown at purchase",
                "Manufacturers shall ensure that the end date of the support period referred to in paragraph 8, including at least the month and the year, is clearly and understandably specified at the time of purchase in an easily accessible manner and, where applicable, on the product with digital elements, its packaging or by digital means. "
                + "Where technically feasible in light of the nature of the product with digital elements, manufacturers shall display a notification to users informing them that their product with digital elements has reached the end of its support period.");
            Add(Art13, "art_13", "Art.13(20)", "A copy of the EU declaration of conformity comes with the product",
                "Manufacturers shall either provide a copy of the EU declaration of conformity or a simplified EU declaration of conformity with the product with digital elements. Where a simplified EU declaration of conformity is provided, it shall contain the exact internet address at which the full EU declaration of conformity can be accessed.");
            Add(Art13, "art_13", "Art.13(21)", "Corrective measures when the product is not in conformity",
                "From the placing on the market and for the support period, manufacturers who know or have reason to believe that the product with digital elements or the processes put in place by the manufacturer are not in conformity with the essential cybersecurity requirements set out in Annex I shall immediately take the corrective measures necessary to bring that product with digital elements or the manufacturer’s processes into conformity, or to withdraw or recall the product, as appropriate.");
            Add(Art13, "art_13", "Art.13(23)", "Authorities and users are told before the manufacturer ceases operations",
                "A manufacturer that ceases its operations and, as a result, is not able to comply with this Regulation shall inform, before the cessation of operations takes effect, the relevant market surveillance authorities as well as, by any means available and to the extent possible, the users of the relevant products with digital elements placed on the market, of the impending cessation of operations.");

            // ------------------------------------------------------------------ Art. 14 (R4: the deadline is in the title)
            Add(Art14, "art_14", "Art.14(1)", "Actively exploited vulnerabilities are notified to the CSIRT and ENISA",
                "A manufacturer shall notify any actively exploited vulnerability contained in the product with digital elements that it becomes aware of simultaneously to the CSIRT designated as coordinator, in accordance with paragraph 7 of this Article, and to ENISA. The manufacturer shall notify that actively exploited vulnerability via the single reporting platform established pursuant to Article 16.");
            Add(Art14, "art_14", "Art.14(2)(a)", "Early warning of an actively exploited vulnerability within 24 hours",
                Art14Point2 + "an early warning notification of an actively exploited vulnerability, without undue delay and in any event within 24 hours of the manufacturer becoming aware of it, indicating, where applicable, the Member States on the territory of which the manufacturer is aware that their product with digital elements has been made available;");
            Add(Art14, "art_14", "Art.14(2)(b)", "Vulnerability notification within 72 hours",
                Art14Point2 + "unless the relevant information has already been provided, a vulnerability notification, without undue delay and in any event within 72 hours of the manufacturer becoming aware of the actively exploited vulnerability, which shall provide general information, as available, about the product with digital elements concerned, the general nature of the exploit and of the vulnerability concerned as well as any corrective or mitigating measures taken, and corrective or mitigating measures that users can take, and which shall also indicate, where applicable, how sensitive the manufacturer considers the notified information to be;");
            Add(Art14, "art_14", "Art.14(2)(c)", "Final report on the vulnerability within 14 days after a fix is available",
                Art14Point2 + "unless the relevant information has already been provided, a final report, no later than 14 days after a corrective or mitigating measure is available, including at least the following: (i) a description of the vulnerability, including its severity and impact; (ii) where available, information concerning any malicious actor that has exploited or that is exploiting the vulnerability; (iii) details about the security update or other corrective measures that have been made available to remedy the vulnerability.");
            Add(Art14, "art_14", "Art.14(3)", "Severe incidents are notified to the CSIRT and ENISA",
                "A manufacturer shall notify any severe incident having an impact on the security of the product with digital elements that it becomes aware of simultaneously to the CSIRT designated as coordinator, in accordance with paragraph 7 of this Article, and to ENISA. The manufacturer shall notify that incident via the single reporting platform established pursuant to Article 16.");
            Add(Art14, "art_14", "Art.14(4)(a)", "Early warning of a severe incident within 24 hours",
                Art14Point4 + "an early warning notification of a severe incident having an impact on the security of the product with digital elements, without undue delay and in any event within 24 hours of the manufacturer becoming aware of it, including at least whether the incident is suspected of being caused by unlawful or malicious acts, which shall also indicate, where applicable, the Member States on the territory of which the manufacturer is aware that their product with digital elements has been made available;");
            Add(Art14, "art_14", "Art.14(4)(b)", "Incident notification within 72 hours",
                Art14Point4 + "unless the relevant information has already been provided, an incident notification, without undue delay and in any event within 72 hours of the manufacturer becoming aware of the incident, which shall provide general information, where available, about the nature of the incident, an initial assessment of the incident, as well as any corrective or mitigating measures taken, and corrective or mitigating measures that users can take, and which shall also indicate, where applicable, how sensitive the manufacturer considers the notified information to be;");
            Add(Art14, "art_14", "Art.14(4)(c)", "Final report on the incident within one month",
                Art14Point4 + "unless the relevant information has already been provided, a final report, within one month after the submission of the incident notification under point (b), including at least the following: (i) a detailed description of the incident, including its severity and impact; (ii) the type of threat or root cause that is likely to have triggered the incident; (iii) applied and ongoing mitigation measures.");
            Add(Art14, "art_14", "Art.14(7)", "Notifications go through the single reporting platform to the right CSIRT",
                "The notifications referred to in paragraphs 1 and 3 of this Article shall be submitted via the single reporting platform referred to in Article 16 using one of the electronic notification end-points referred to in Article 16(1). The notification shall be submitted using the electronic notification end-point of the CSIRT designated as coordinator of the Member State where the manufacturers have their main establishment in the Union and shall be simultaneously accessible to ENISA. "
                + "For the purposes of this Regulation, a manufacturer shall be considered to have its main establishment in the Union in the Member State where the decisions related to the cybersecurity of its products with digital elements are predominantly taken. If such a Member State cannot be determined, the main establishment shall be considered to be in the Member State where the manufacturer concerned has the establishment with the highest number of employees in the Union. "
                + "Where a manufacturer has no main establishment in the Union, it shall submit the notifications referred to in paragraphs 1 and 3 using the electronic notification end-point of the CSIRT designated as coordinator in the Member State determined pursuant to the following order and based on the information available to the manufacturer: (a) the Member State in which the authorised representative acting on behalf of the manufacturer for the highest number of products with digital elements of that manufacturer is established; (b) the Member State in which the importer placing on the market the highest number of products with digital elements of that manufacturer is established; (c) the Member State in which the distributor making available on the market the highest number of products with digital elements of that manufacturer is established; (d) the Member State in which the highest number of users of products with digital elements of that manufacturer are located.");
            Add(Art14, "art_14", "Art.14(8)", "Impacted users are informed of the vulnerability or incident",
                "After becoming aware of an actively exploited vulnerability or a severe incident having an impact on the security of the product with digital elements, the manufacturer shall inform the impacted users of the product with digital elements, and where appropriate all users, of that vulnerability or incident and, where necessary, of any risk mitigation and corrective measures that the users can deploy to mitigate the impact of that vulnerability or incident, where appropriate in a structured, machine-readable format that is easily automatically processable. Where the manufacturer fails to inform the users of the product with digital elements in a timely manner, the notified CSIRTs designated as coordinators may provide such information to the users when considered to be proportionate and necessary for preventing or mitigating the impact of that vulnerability or incident.");

            // ------------------------------------------------------------------ Art. 28–32
            Add(Conformity, "art_28", "Art.28", "The EU declaration of conformity (Annexes V and VI)",
                "The EU declaration of conformity shall be drawn up by manufacturers in accordance with Article 13(12) and state that the fulfilment of the applicable essential cybersecurity requirements set out in Annex I has been demonstrated. "
                + "The EU declaration of conformity shall have the model structure set out in Annex V and shall contain the elements specified in the relevant conformity assessment procedures set out in Annex VIII. Such a declaration shall be updated as appropriate. It shall be made available in the languages required by the Member State in which the product with digital elements is placed on the market or made available on the market. "
                + "The simplified EU declaration of conformity referred to in Article 13(20) shall have the model structure set out in Annex VI. It shall be made available in the languages required by the Member State in which the product with digital elements is placed on the market or made available on the market. "
                + "Where a product with digital elements is subject to more than one Union legal act requiring an EU declaration of conformity, a single EU declaration of conformity shall be drawn up in respect of all such Union legal acts. That declaration shall contain the identification of the Union legal acts concerned, including their publication references. "
                + "By drawing up the EU declaration of conformity, the manufacturer shall assume responsibility for the compliance of the product with digital elements.");
            Add(Conformity, "art_30", "Art.30", "The CE marking is affixed visibly before the product is placed on the market",
                "The CE marking shall be affixed visibly, legibly and indelibly to the product with digital elements. Where that is not possible or not warranted on account of the nature of the product with digital elements, it shall be affixed to the packaging and to the EU declaration of conformity referred to in Article 28 accompanying the product with digital elements. For products with digital elements which are in the form of software, the CE marking shall be affixed either to the EU declaration of conformity referred to in Article 28 or on the website accompanying the software product. In the latter case, the relevant section of the website shall be easily and directly accessible to consumers. "
                + "The CE marking shall be affixed before the product with digital elements is placed on the market. It may be followed by a pictogram or any other mark indicating a special cybersecurity risk or use set out in the implementing acts referred to in paragraph 6. "
                + "The CE marking shall be followed by the identification number of the notified body, where that body is involved in the conformity assessment procedure based on full quality assurance (based on module H) referred to in Article 32.");
            Add(Conformity, "art_31", "Art.31", "Technical documentation after Annex VII, kept up to date",
                "The technical documentation shall contain all relevant data or details of the means used by the manufacturer to ensure that the product with digital elements and the processes put in place by the manufacturer comply with the essential cybersecurity requirements set out in Annex I. It shall at least contain the elements set out in Annex VII. "
                + "The technical documentation shall be drawn up before the product with digital elements is placed on the market and shall be continuously updated, where appropriate, at least during the support period. "
                + "For products with digital elements as referred to in Article 12, which are also subject to other Union legal acts which provide for technical documentation, a single set of technical documentation shall be drawn up containing the information referred to in Annex VII and the information required by those Union legal acts.");
            Add(Conformity, "art_32", "Art.32", "A conformity assessment with one of the procedures (Annex VIII)",
                "The manufacturer shall perform a conformity assessment of the product with digital elements and the processes put in place by the manufacturer to determine whether the essential cybersecurity requirements set out in Annex I are met. The manufacturer shall demonstrate conformity with the essential cybersecurity requirements by using any of the following procedures: (a) the internal control procedure (based on module A) set out in Annex VIII; (b) the EU-type examination procedure (based on module B) set out in Annex VIII followed by conformity to EU-type based on internal production control (based on module C) set out in Annex VIII; (c) a conformity assessment based on full quality assurance (based on module H) set out in Annex VIII; or (d) where available and applicable, a European cybersecurity certification scheme pursuant to Article 27(9). "
                + "Where the product is an important product with digital elements that falls under class II as set out in Annex III, the manufacturer shall demonstrate conformity with the essential cybersecurity requirements set out in Annex I by using any of the following procedures: (a) EU-type examination procedure (based on module B) set out in Annex VIII followed by conformity to EU-type based on internal production control (based on module C) set out in Annex VIII; (b) a conformity assessment based on full quality assurance (based on module H) set out in Annex VIII; or (c) where available and applicable, a European cybersecurity certification scheme pursuant to Article 27(9) of this Regulation at assurance level at least ‘substantial’ pursuant to Regulation (EU) 2019/881. "
                + "Critical products with digital elements listed in Annex IV shall demonstrate conformity with the essential cybersecurity requirements set out in Annex I by using one of the following procedures: (a) a European cybersecurity certification scheme in accordance with Article 8(1); or (b) where the conditions in Article 8(1) are not met, any of the procedures referred to in paragraph 3 of this Article.");

            // ------------------------------------------------------------------ Annex II (R5: one requirement per point)
            Add(AnnexII, "anx_II", "Annex II.1", "The manufacturer's name and contact details",
                AnnexIILeadIn + "the name, registered trade name or registered trademark of the manufacturer, and the postal address, the email address or other digital contact as well as, where available, the website at which the manufacturer can be contacted;");
            Add(AnnexII, "anx_II", "Annex II.2", "The single point of contact for vulnerabilities and the disclosure policy",
                AnnexIILeadIn + "the single point of contact where information about vulnerabilities of the product with digital elements can be reported and received, and where the manufacturer’s policy on coordinated vulnerability disclosure can be found;");
            Add(AnnexII, "anx_II", "Annex II.3", "Name and type that identify the product",
                AnnexIILeadIn + "name and type and any additional information enabling the unique identification of the product with digital elements;");
            Add(AnnexII, "anx_II", "Annex II.4", "Intended purpose, essential functions and security properties",
                AnnexIILeadIn + "the intended purpose of the product with digital elements, including the security environment provided by the manufacturer, as well as the product’s essential functionalities and information about the security properties;");
            Add(AnnexII, "anx_II", "Annex II.5", "Known or foreseeable circumstances that may lead to significant risks",
                AnnexIILeadIn + "any known or foreseeable circumstance, related to the use of the product with digital elements in accordance with its intended purpose or under conditions of reasonably foreseeable misuse, which may lead to significant cybersecurity risks;");
            Add(AnnexII, "anx_II", "Annex II.6", "Where the EU declaration of conformity can be found",
                AnnexIILeadIn + "where applicable, the internet address at which the EU declaration of conformity can be accessed;");
            Add(AnnexII, "anx_II", "Annex II.7", "The type of technical security support and the end date of the support period",
                AnnexIILeadIn + "the type of technical security support offered by the manufacturer and the end-date of the support period during which users can expect vulnerabilities to be handled and to receive security updates;");
            Add(AnnexII, "anx_II", "Annex II.8", "Instructions for secure use, updates, decommissioning and integration",
                AnnexIILeadIn + "detailed instructions or an internet address referring to such detailed instructions and information on: (a) the necessary measures during initial commissioning and throughout the lifetime of the product with digital elements to ensure its secure use; (b) how changes to the product with digital elements can affect the security of data; (c) how security-relevant updates can be installed; (d) the secure decommissioning of the product with digital elements, including information on how user data can be securely removed; (e) how the default setting enabling the automatic installation of security updates, as required by Part I, point (2)(c), of Annex I, can be turned off; (f) where the product with digital elements is intended for integration into other products with digital elements, the information necessary for the integrator to comply with the essential cybersecurity requirements set out in Annex I and the documentation requirements set out in Annex VII.");
            Add(AnnexII, "anx_II", "Annex II.9", "Where the SBOM can be found, if it is made available",
                AnnexIILeadIn + "If the manufacturer decides to make available the software bill of materials to the user, information on where the software bill of materials can be accessed.");

            // ------------------------------------------------------------------ Annex VII (R5: one requirement per point)
            Add(AnnexVII, "anx_VII", "Annex VII.1", "A general description of the product",
                AnnexVIILeadIn + "a general description of the product with digital elements, including: (a) its intended purpose; (b) versions of software affecting compliance with essential cybersecurity requirements; (c) where the product with digital elements is a hardware product, photographs or illustrations showing external features, marking and internal layout; (d) user information and instructions as set out in Annex II;");
            Add(AnnexVII, "anx_VII", "Annex VII.2", "Design, development, production and vulnerability handling",
                AnnexVIILeadIn + "a description of the design, development and production of the product with digital elements and vulnerability handling processes, including: (a) necessary information on the design and development of the product with digital elements, including, where applicable, drawings and schemes and a description of the system architecture explaining how software components build on or feed into each other and integrate into the overall processing; (b) necessary information and specifications of the vulnerability handling processes put in place by the manufacturer, including the software bill of materials, the coordinated vulnerability disclosure policy, evidence of the provision of a contact address for the reporting of the vulnerabilities and a description of the technical solutions chosen for the secure distribution of updates; (c) necessary information and specifications of the production and monitoring processes of the product with digital elements and the validation of those processes;");
            Add(AnnexVII, "anx_VII", "Annex VII.3", "The cybersecurity risk assessment",
                AnnexVIILeadIn + "an assessment of the cybersecurity risks against which the product with digital elements is designed, developed, produced, delivered and maintained pursuant to Article 13, including how the essential cybersecurity requirements set out in Part I of Annex I are applicable;");
            Add(AnnexVII, "anx_VII", "Annex VII.4", "What was taken into account to determine the support period",
                AnnexVIILeadIn + "relevant information that was taken into account to determine the support period pursuant to Article 13(8) of the product with digital elements;");
            Add(AnnexVII, "anx_VII", "Annex VII.5", "Standards, specifications and certification schemes applied",
                AnnexVIILeadIn + "a list of the harmonised standards applied in full or in part the references of which have been published in the Official Journal of the European Union, common specifications as set out in Article 27 of this Regulation or European cybersecurity certification schemes adopted pursuant to Regulation (EU) 2019/881 pursuant to Article 27(8) of this Regulation, and, where those harmonised standards, common specifications or European cybersecurity certification schemes have not been applied, descriptions of the solutions adopted to meet the essential cybersecurity requirements set out in Parts I and II of Annex I, including a list of other relevant technical specifications applied. In the event of partly applied harmonised standards, common specifications or European cybersecurity certification schemes, the technical documentation shall specify the parts which have been applied;");
            Add(AnnexVII, "anx_VII", "Annex VII.6", "Reports of the conformity tests",
                AnnexVIILeadIn + "reports of the tests carried out to verify the conformity of the product with digital elements and of the vulnerability handling processes with the applicable essential cybersecurity requirements as set out in Parts I and II of Annex I;");
            Add(AnnexVII, "anx_VII", "Annex VII.7", "A copy of the EU declaration of conformity",
                AnnexVIILeadIn + "a copy of the EU declaration of conformity;");
            Add(AnnexVII, "anx_VII", "Annex VII.8", "The SBOM, when the market surveillance authority asks for it",
                AnnexVIILeadIn + "where applicable, the software bill of materials, further to a reasoned request from a market surveillance authority provided that it is necessary in order for that authority to be able to check compliance with the essential cybersecurity requirements set out in Annex I.");

